local util = require 'XLua.util'
local KTool = CS.Engine.Lib.KTool
local UIModule = CS.Engine.UI.UIModule
local CommonMonstCardNode = "Game.Behaviours.CommonMonstCardNode"
local MAXENEMYNUM = 4
---@class UIFightTeamEnemysNode
---@field CardPar                       	UnityEngine.RectTransform                            
local UIFightTeamEnemysNode = Class("UIFightTeamEnemysNode")
function UIFightTeamEnemysNode:__init() 
    self._data = nil
end

function UIFightTeamEnemysNode:__delete()
    self._data = nil
end

function UIFightTeamEnemysNode:Awake()
    CfUtils.FillText(self.TitleName, localize("敌方情报"))
end

function UIFightTeamEnemysNode:Start()
end

function UIFightTeamEnemysNode:Refresh(data, levelId)
    if not data or table.count(data) <= 0 then
        KTool.SetActive(self.controller.gameObject, false)
        return
    end
    self._data = data

    local type = GoodsUtils.GetIdType(levelId, Constants.IDArea.Quests)     --关卡类型
    for i = 1, 4 do
        local go = self["CommonMonstCardNode"..i]
        if go then
            KTool.SetActive(go, false)
        end
    end
    for i = 1, #data do
        local go = self["CommonMonstCardNode"..i]
        if go then
            KTool.SetActive(go, true)
            local scr = CfUtils.GetLuaScr(go, CommonMonstCardNode)
            if scr then
                scr:RefeshInfo(data[i].id, data[i], data[i].level, data[i].attr, data[i].grade)
                --迷宫关掉
                if type == Constants.IDType.QuestMaze then
                    scr:SetLevelActive(false)
                end
            end
        end
    end
end

function UIFightTeamEnemysNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIFightTeamEnemysNode
